      safety: {
        st1Title: "What KunThai can do",
        st1Body: "KunThai can give operators better guidance, route context, trip records, passenger request details, safety reminders, and reporting tools. KunThai cannot physically protect an operator or passenger, control road conditions, or replace emergency services. When life, health, violence, fire, crash, or serious danger is involved, emergency help and nearby trusted people must come first.",
        st2Title: "Professional duty before accepting",
        st2Body: "Accept only the trips you can safely complete. Check pickup point, destination, fleet type, passenger count, parcel details, and any special notes. If the trip is outside your service area, unsafe for your fleet, overloaded, or unclear, do not accept it just to win the request.",
        st3Title: "Arrival protocol",
        st3Body: "Arrive at the pickup point shown in the booking, identify yourself calmly, and let the passenger confirm your operator name, fleet type, and plate number. Do not pressure a passenger to enter if they are still checking details. A professional operator makes the passenger feel safe before the trip starts.",
        st4Title: "Passenger respect and boundaries",
        st4Body: "Avoid harassment, insults, threats, aggressive bargaining, or unnecessary personal questions. Keep communication focused on pickup, route, fare, delivery, and safety. If a passenger is distressed, confused, elderly, disabled, or travelling with a child, slow down the interaction and make the process clear.",
        st5Title: "Route discipline",
        st5Body: "Follow the agreed route or the route shown in area view unless traffic, road closure, danger, or passenger instruction requires a change. If you must change route, explain it before or immediately after the change. Sudden unexplained detours create fear and can become a safety report.",
        st6Title: "Emergency handling",
        st6Body: "In a crash, medical problem, violence, fire, robbery, or serious road danger, stop in the safest available place, contact local emergency help, and protect people before protecting the trip record. After urgent help is contacted, record the trip details, passenger name, location, time, and what happened for support follow-up.",
        st7Title: "Conflict and fare disagreement",
        st7Body: "Do not escalate arguments on the roadside. If a fare, route, or delivery disagreement happens, keep your voice low, move to a public and safer place where possible, and preserve the trip details. Support can understand a calm report better than a heated argument with missing facts.",
        st8Title: "Delivery safety",
        st8Body: "Check parcel description, pickup person, receiver details, payment responsibility, and drop-off location before moving. Do not carry suspicious, dangerous, illegal, leaking, or poorly described items. If the receiver cannot be verified, document the issue and contact support instead of abandoning the parcel without record.",
        st9Title: "Reporting as an operator",
        st9Body: "Report passenger threats, unsafe pickup locations, fake bookings, harassment, unpaid fares, dangerous parcels, wrong saved locations, or route incidents with clear details. Include route, time, passenger name, phone if available, screenshots, and what action you took to keep people safe.",
      },
      deletionBack: "Back to operator menu",
      deletionEyebrow: "Operator Account",
      deletionTitle: "Request account deletion",
