      menuNote: "Vous pouvez retrouver cette carte de précaution à tout moment dans le menu de l'en-tête du tableau de bord passager.",
      eyebrow: "Sécurité et vérification UrRide",
      heading: "N'enregistrez que de vrais opérateurs, flottes et sociétés de transport",
      intro: "UrRide met en relation passagers, opérateurs, livraisons et sociétés, mais chaque compte est responsable de l'exactitude des documents, de la véracité des détails de la flotte, d'une exploitation conforme à la loi et d'une conduite sûre avant chaque trajet.",
      v1Title: "Preuve d'identité, de permis et de flotte",
      v1Body: "La vérification UrRide peut exiger une pièce d'identité officielle, un permis de conduire ou de conducteur, une carte grise, une assurance, un contrôle technique, des photos de la flotte et d'autres documents applicables dans le pays sélectionné.",
      v2Title: "Inscrivez-vous d'abord, complétez la vérification plus tard",
      v2Body: "Un opérateur indépendant peut continuer sans tous les documents et téléverser les fichiers manquants plus tard. Tant que l'examen n'est pas terminé, le compte reste Non vérifié et les passagers doivent redoubler de prudence.",
      v3Title: "L'approbation est un signal de sécurité",
      v3Body: "Le statut vérifié ou recommandé signifie que KunThai a examiné les informations requises. Il ne remplace pas le jugement du passager, la sécurité routière, la loi locale ou les services d'urgence.",
      beforeTitle: "Avant qu'un passager ne monte dans un véhicule",
      beforeBody: "Confirmez l'opérateur, la plaque d'immatriculation, le type de flotte, le point de prise en charge, la destination, le tarif et les places disponibles avant le début du trajet.",
      o1Title: "Opérateurs indépendants",
      o1Body: "Utilisez votre véritable identité, un numéro de téléphone joignable, la bonne zone de service, un permis valide, des tarifs honnêtes et la flotte réelle que les passagers verront.",
      o2Title: "Détails de la flotte et du véhicule",
      o2Body: "Les photos de la flotte, les numéros de plaque, les informations sur les sièges et les réponses de sécurité doivent correspondre au véhicule utilisé pour les trajets ou les livraisons.",
      o3Title: "Comptes de société",
      o3Body: "Une société enregistre l'organisation et les flottes, puis invite les opérateurs via l'identifiant KunThai public de chacun. Les opérateurs conservent leur propre compte et ne doivent jamais partager un mot de passe.",
      security: "N'entrez pas dans un véhicule lorsque l'opérateur, la flotte, la plaque ou l'itinéraire diffère de l'application. Rendez-vous dans un lieu public, annulez la demande et utilisez les outils de sécurité ou d'assistance si quelque chose vous semble anormal.",
