        safetyTitle: "Sécurité des paiements",
        body: "Les paiements de transport et la recharge de portefeuille KunThai ne sont pas encore actifs. Nous conservons ce champ jusqu'à ce que les paiements puissent être liés à un trajet vérifié, un opérateur vérifié, un reçu et un dossier d'assistance clair. C'est plus sûr pour les passagers et plus professionnel pour les opérateurs que d'afficher un formulaire de paiement avant que le service ne puisse protéger la transaction.",
        forNowTitle: "Pour l'instant",
        forNowBody: "Confirmez l'itinéraire, le tarif, l'identité de l'opérateur, la plaque de la flotte, le point de prise en charge, la destination et le mode de paiement prévu avant de payer.",
        secretsTitle: "Ne partagez pas de secrets",
        secretsBody: "N'entrez jamais et n'envoyez jamais de codes PIN de portefeuille, d'OTP, de détails complets de carte ou de mots de passe de compte via un message de trajet ou une note d'assistance.",
        proofTitle: "Conservez une preuve",
        proofBody: "Gardez visibles le dossier du trajet, le nom de l'opérateur, la confirmation de paiement et la conversation jusqu'à ce que la course ou la livraison soit terminée.",
        tempNoteTitle: "Note de paiement passager temporaire",
